/**
 * Toast (D46, D78): the result of a reversible action outside the primary action, for example „Glas eingetragen ·
 * 6 / 8“ with „Rückgängig“. Ground bg, the 2 dp ink layer line, radius container, no shadow. Never for errors, never
 * instead of the delete dialog (D39). The caller owns the timing and keeps the toast while it has focus.
 */
@Composable
fun SbToast(
    message: String,
    modifier: Modifier = Modifier,
    actionLabel: String? = null,
    onAction: () -> Unit = {},
) {
    val t = SebaroTheme.tokens
    val overlay = t.elevation.overlay
    Surface(
        modifier = modifier
            .fillMaxWidth()
            .heightIn(min = t.size.controlMd)
            .semantics { liveRegion = LiveRegionMode.Polite },
        shape = t.shapes.container,
        color = overlay.surface,
        contentColor = SebaroTheme.colors.text,
        border = BorderStroke(overlay.borderWidth, overlay.borderColor),
        shadowElevation = overlay.shadowElevation,
    ) {
        // D99 (1): the action stands after the message while the message's widest word fits beside it; else it goes
        // under the message, at the end, and the message takes the whole width (the toast grows), never a word cut
        val style = SebaroTheme.typography.numeric
        val measurer = rememberTextMeasurer()
        val widest = remember(message, style, measurer) { measurer.sbWidestWord(message, style) }
        Layout(
            content = {
                SbWrapText(message, style, SebaroTheme.colors.text)
                if (actionLabel != null) SbTextActionView(actionLabel, onAction, ringInside = true)
            },
            modifier = Modifier.padding(start = t.space.s4, top = t.space.s1, end = t.space.s1, bottom = t.space.s1),
        ) { measurables, constraints ->
            val loose = constraints.copy(minWidth = 0, minHeight = 0)
            val action = measurables.getOrNull(1)?.measure(loose)
            val w = constraints.maxWidth
            val room = w - (action?.width ?: 0)
            // §14.1: a message on more than one line (or with the action under it) keeps 12 dp above and below
            val oneLine = style.lineHeight.roundToPx()
            val extra = (t.space.s3 - t.space.s1).roundToPx()
            if (action == null || widest <= room) {
                val words = measurables[0].measure(loose.copy(maxWidth = room))
                val pad = if (words.height > oneLine * 3 / 2) extra else 0
                val h = maxOf(constraints.minHeight, words.height + 2 * pad, action?.height ?: 0)
                layout(w, h) {
                    words.placeRelative(0, ((h - words.height) / 2f).roundToInt())
                    action?.placeRelative(w - action.width, ((h - action.height) / 2f).roundToInt())
                }
            } else {
                val words = measurables[0].measure(loose)
                val h = maxOf(constraints.minHeight, words.height + action.height + extra)
                layout(w, h) {
                    words.placeRelative(0, extra)
                    action.placeRelative(w - action.width, extra + words.height)
                }
            }
        }
    }
}

/** One toast for [SbToastHost]: the [message], an optional [actionLabel] („Rückgängig“) and what it does. */
@Immutable
data class SbToastData(val message: String, val actionLabel: String? = null, val onAction: () -> Unit = {})

/** The toast an SbToastHost shows (§14.1): [show] replaces the current one, [dismiss] closes it. */
@Stable
class SbToastState {
    var current by mutableStateOf<SbToastData?>(null)
        private set
    internal var hasFocus by mutableStateOf(false)
    internal var returnTo by mutableStateOf<FocusRequester?>(null)

    fun show(data: SbToastData) {
        current = data
    }

    fun dismiss() {
        current = null
    }
}

/** The state of a screen's toasts. */
@Composable
fun rememberSbToastState(): SbToastState = remember { SbToastState() }

/**
 * Marks the list that [state]'s toast returns to (CHECKS.md §87; provisional, agent): Up from the toast and its closing
 * lead to the part of the list the focus came from. The part is remembered only on that way, while the toast stands and
 * the focus is in the list or went from it to the toast. So Tab goes through the whole list, and a request reaches its target.
 * [restorer] is the app's `Modifier.focusRestorer()`: its signature differs between Compose versions, so a package must not call it.
 */
@Composable
fun Modifier.sbToastReturn(state: SbToastState, restorer: Modifier): Modifier {
    val requester = remember { FocusRequester() }
    DisposableEffect(state, requester) {
        state.returnTo = requester
        onDispose { state.returnTo = null }
    }
    var inList by remember { mutableStateOf(false) }
    // no state: written in the composition and read only here; both focus values trigger it
    val keeps = remember { booleanArrayOf(false) }
    keeps[0] = state.current != null && (inList || (state.hasFocus && keeps[0]))
    return focusRequester(requester).then(if (keeps[0]) restorer else Modifier).onFocusChanged { inList = it.hasFocus }
}

/**
 * Shows [state]'s toast in the gutter (§14.1; EBE-05): [durationMs] (6 s), longer when the system asks for it
 * (TalkBack, the „time to act“ setting), held while it has focus or a finger on it; Escape and its action close it.
 * [upTo] (CHECKS.md §85; provisional, agent): where Up leads from the toast, and so where the focus goes when it closes;
 * without it the list marked with [sbToastReturn]. The toast lies over the list, so the search upward passes the list and
 * lands in the top bar.
 */
@Composable
fun SbToastHost(state: SbToastState, modifier: Modifier = Modifier, durationMs: Long = 6_000L, upTo: FocusRequester? = null) {
    val data = state.current ?: return
    val t = SebaroTheme.tokens
    val a11y = LocalAccessibilityManager.current
    var focused by remember(data) { mutableStateOf(false) }
    var touched by remember(data) { mutableStateOf(false) }
    val wait = a11y?.calculateRecommendedTimeoutMillis(
        durationMs,
        containsIcons = false,
        containsText = true,
        containsControls = data.actionLabel != null,
    ) ?: durationMs
    LaunchedEffect(data, focused, touched) {
        if (!focused && !touched) {
            delay(wait)
            state.dismiss()
        }
    }
    val shown = remember(data) { MutableTransitionState(false).apply { targetState = true } }
    val focusManager = LocalFocusManager.current
    // CHECKS.md §85: the focus goes up before the toast closes, or it has no place left; the app may then move it on
    val leave = { if (focused) focusManager.moveFocus(FocusDirection.Up) }
    val focusRoom = LocalSbFocusRoom.current
    DisposableEffect(focusRoom) { onDispose { focusRoom?.toast = 0 } }
    DisposableEffect(state) { onDispose { state.hasFocus = false } }
    val upward = upTo ?: state.returnTo
    AnimatedVisibility(visibleState = shown, enter = sbEnter(), modifier = modifier.onSizeChanged { focusRoom?.toast = it.height }) {
        Box(
            Modifier
                .padding(horizontal = t.spacing.gutter, vertical = t.space.s2)
                .focusProperties { if (upward != null) up = upward }
                .onFocusChanged {
                    focused = it.hasFocus
                    state.hasFocus = it.hasFocus
                }
                .onPreviewKeyEvent { e ->
                    if (e.key == Key.Escape && e.type == KeyEventType.KeyUp) {
                        leave()
                        state.dismiss()
                        true
                    } else {
                        e.key == Key.Escape
                    }
                }
                .pointerInput(data) {
                    awaitEachGesture {
                        awaitFirstDown(requireUnconsumed = false, pass = PointerEventPass.Initial)
                        touched = true
                        waitForUpOrCancellation(PointerEventPass.Initial)
                        touched = false
                    }
                },
        ) {
            SbToast(
                data.message,
                actionLabel = data.actionLabel,
                onAction = {
                    leave()
                    data.onAction()
                    state.dismiss()
                },
            )
        }
    }
}

@Deprecated("Binary bridge before upTo", level = DeprecationLevel.HIDDEN)
@Composable
fun SbToastHost(state: SbToastState, modifier: Modifier = Modifier, durationMs: Long = 6_000L) {
    SbToastHost(state, modifier, durationMs, null)
}
